/** CI recipes, byte for byte equal to the files in examples/ci/. */
export const CI_TEMPLATES = {
  /** examples/ci/github-actions.yml */
  github:
    '# Performance runs with playwright-performance-regression (pw-perf). Save as\n# .github/workflows/perf.yml. Recommended path (docs/ci.md):\n#   1. Run the "thresholds" job by hand (Actions > Performance > Run workflow, mode: thresholds).\n#      Thresholds come from the same machines that measure.\n#   2. Download the pw-perf-thresholds artifact and commit its pw-perf-thresholds*.json files.\n#   3. The "measure" job runs every Monday (or by hand, mode: test) and fails on a regression.\n# The exit code comes from reports/pw-perf/outcome.json: 0 ok, 2 performance regression, 3 tool or\n# config error. Not ready to block builds? Add "continue-on-error: true" to the measure job.\nname: Performance\n\non:\n  schedule:\n    - cron: \'0 3 * * 1\'\n  workflow_dispatch:\n    inputs:\n      mode:\n        description: \'test: measurement run, thresholds: derive the thresholds files\'\n        type: choice\n        options: [test, thresholds]\n        default: test\n\njobs:\n  thresholds:\n    if: github.event_name == \'workflow_dispatch\' && inputs.mode == \'thresholds\'\n    runs-on: ubuntu-latest\n    timeout-minutes: 120\n    env:\n      PW_PERF_MODE: thresholds\n    steps:\n      - uses: actions/checkout@v7\n      - uses: actions/setup-node@v7\n        with:\n          node-version: 22\n          cache: npm\n      - run: npm ci\n      - run: npx playwright install --with-deps chromium\n      - name: Thresholds run\n        run: |\n          rm -f reports/pw-perf/outcome.json\n          npm run e2e || true\n          exit "$(node -p "require(\'./reports/pw-perf/outcome.json\').exitCode" 2>/dev/null || echo 3)"\n      - name: Upload the thresholds files\n        if: always()\n        uses: actions/upload-artifact@v7\n        with:\n          name: pw-perf-thresholds\n          path: |\n            pw-perf-thresholds*.json\n            reports/pw-perf/\n          retention-days: 30\n\n  measure:\n    if: github.event_name == \'schedule\' || inputs.mode == \'test\'\n    runs-on: ubuntu-latest\n    timeout-minutes: 60\n    env:\n      PW_PERF_MODE: test\n    steps:\n      - uses: actions/checkout@v7\n      - uses: actions/setup-node@v7\n        with:\n          node-version: 22\n          cache: npm\n      - run: npm ci\n      - run: npx playwright install --with-deps chromium\n      - name: Measurement run\n        run: |\n          rm -f reports/pw-perf/outcome.json\n          npm run e2e || true\n          exit "$(node -p "require(\'./reports/pw-perf/outcome.json\').exitCode" 2>/dev/null || echo 3)"\n      - name: Upload the performance report\n        if: always()\n        uses: actions/upload-artifact@v7\n        with:\n          name: pw-perf-report\n          path: reports/pw-perf/\n          retention-days: 30\n      # Optional: GitHub has no test view of its own; reports/pw-perf/junit.xml is in the\n      # pw-perf-report artifact. To show it as a check run, add "permissions: checks: write" to\n      # this job and uncomment a test report action, e.g.:\n      # - name: Show the JUnit result\n      #   if: always()\n      #   uses: mikepenz/action-junit-report@v5\n      #   with:\n      #     report_paths: reports/pw-perf/junit.xml\n',
  /** examples/ci/gitlab-ci.yml */
  gitlab:
    '# Performance runs with playwright-performance-regression (pw-perf). Save as\n# .gitlab/perf.gitlab-ci.yml and include it from .gitlab-ci.yml. Recommended path (docs/ci.md):\n#   1. Start the manual "perf-thresholds" job. Thresholds come from the same runners that measure.\n#   2. Download its artifacts and commit the pw-perf-thresholds*.json files.\n#   3. The "perf" job runs in scheduled pipelines (create a weekly schedule) and can be started by\n#      hand; it fails on a regression.\n# The exit code comes from reports/pw-perf/outcome.json: 2 (performance regression) is a soft\n# failure, 3 (tool or config error) fails the job. The perf job also publishes\n# reports/pw-perf/junit.xml: the Tests tab of the pipeline and the merge request widget show each\n# endpoint and step; the job status still comes from outcome.json only.\n.perf:\n  image: node:22\n  before_script:\n    - npm ci\n    - npx playwright install --with-deps chromium\n  script:\n    - rm -f reports/pw-perf/outcome.json\n    - npm run e2e || true\n    - exit "$(node -p "require(\'./reports/pw-perf/outcome.json\').exitCode" 2>/dev/null || echo 3)"\n\nperf-thresholds:\n  extends: .perf\n  timeout: 2h\n  variables:\n    PW_PERF_MODE: thresholds\n  rules:\n    - when: manual\n  allow_failure: true\n  artifacts:\n    when: always\n    paths:\n      - pw-perf-thresholds*.json\n      - reports/pw-perf/\n    expire_in: 30 days\n\nperf:\n  extends: .perf\n  timeout: 1h\n  variables:\n    PW_PERF_MODE: test\n  rules:\n    - if: $CI_PIPELINE_SOURCE == "schedule"\n    - when: manual\n      allow_failure: true\n  allow_failure:\n    exit_codes: 2\n  artifacts:\n    when: always\n    paths:\n      - reports/pw-perf/\n    reports:\n      junit: reports/pw-perf/junit.xml\n    expire_in: 30 days\n',
  /** examples/ci/Jenkinsfile */
  jenkins:
    "// Performance runs with playwright-performance-regression (pw-perf). Use as the script of a\n// pipeline job, e.g. \"Jenkinsfile.perf\". Recommended path (docs/ci.md):\n//   1. Build with parameters, MODE=thresholds. Thresholds come from the same agents that measure.\n//   2. Download the archived pw-perf-thresholds*.json files and commit them.\n//   3. The job runs every Monday with MODE=test and fails on a regression.\n// The exit code comes from reports/pw-perf/outcome.json: 2 (performance regression) marks the\n// build UNSTABLE, 3 (tool or config error) fails it. The JUnit plugin shows\n// reports/pw-perf/junit.xml (MODE=test) as Test Result; it never changes the build status.\npipeline {\n  agent any\n  parameters {\n    choice(name: 'MODE', choices: ['test', 'thresholds'], description: 'test: measurement run, thresholds: derive the thresholds files')\n  }\n  options {\n    timeout(time: 120, unit: 'MINUTES')\n  }\n  triggers {\n    cron('H 3 * * 1')\n  }\n  environment {\n    PW_PERF_MODE = \"${params.MODE ?: 'test'}\"\n  }\n  stages {\n    stage('Performance') {\n      steps {\n        sh 'npm ci'\n        sh 'npx playwright install --with-deps chromium'\n        sh 'rm -f reports/pw-perf/outcome.json'\n        sh(script: 'npm run e2e', returnStatus: true)\n        script {\n          def code = sh(script: 'node -p \"require(\\'./reports/pw-perf/outcome.json\\').exitCode\" 2>/dev/null || echo 3', returnStdout: true).trim()\n          if (code == '2') {\n            unstable('Performance regression (exit code 2)')\n          } else if (code != '0') {\n            error(\"Performance run failed with exit code ${code}\")\n          }\n        }\n      }\n    }\n  }\n  post {\n    always {\n      archiveArtifacts artifacts: 'pw-perf-thresholds*.json, reports/pw-perf/**', allowEmptyArchive: true\n      junit testResults: 'reports/pw-perf/junit.xml', allowEmptyResults: true, skipMarkingBuildUnstable: true\n    }\n  }\n}\n",
  /** examples/ci/azure-pipelines.yml */
  azure:
    "# Performance runs with playwright-performance-regression (pw-perf). Register as its own\n# pipeline, e.g. azure-pipelines.perf.yml. Recommended path (docs/ci.md):\n#   1. Run the pipeline by hand with mode \"thresholds\". Thresholds come from the same agents\n#      that measure.\n#   2. Download the pw-perf-thresholds artifact and commit its pw-perf-thresholds*.json files.\n#   3. The pipeline runs every Monday with mode \"test\" and fails on a regression.\n# The exit code comes from reports/pw-perf/outcome.json: 2 (performance regression) ends the job\n# as \"succeeded with issues\", 3 (tool or config error) fails it. In mode \"test\" the run also\n# publishes reports/pw-perf/junit.xml to the Tests tab; that step never fails the job.\ntrigger: none\npr: none\n\nparameters:\n  - name: mode\n    displayName: 'test: measurement run, thresholds: derive the thresholds files'\n    type: string\n    default: test\n    values: [test, thresholds]\n\nschedules:\n  - cron: '0 3 * * 1'\n    displayName: Weekly measurement run\n    branches:\n      include:\n        - main\n    always: true\n\npool:\n  vmImage: ubuntu-latest\n\njobs:\n  - job: perf\n    timeoutInMinutes: 120\n    variables:\n      PW_PERF_MODE: ${{ parameters.mode }}\n    steps:\n      - task: NodeTool@0\n        inputs:\n          versionSpec: '22.x'\n      - script: npm ci\n        displayName: Install dependencies\n      - script: npx playwright install --with-deps chromium\n        displayName: Install Chromium\n      - bash: |\n          rm -f reports/pw-perf/outcome.json\n          npm run e2e || true\n          code=$(node -p \"require('./reports/pw-perf/outcome.json').exitCode\" 2>/dev/null || echo 3)\n          if [ \"$code\" -eq 2 ]; then\n            echo \"##vso[task.complete result=SucceededWithIssues;]Performance regression (exit code 2)\"\n            exit 0\n          fi\n          exit $code\n        displayName: Performance run\n      - bash: mkdir -p pw-perf-thresholds && cp pw-perf-thresholds*.json pw-perf-thresholds/\n        condition: and(always(), eq('${{ parameters.mode }}', 'thresholds'))\n        displayName: Collect the thresholds files\n      - publish: pw-perf-thresholds\n        artifact: pw-perf-thresholds\n        condition: and(always(), eq('${{ parameters.mode }}', 'thresholds'))\n        displayName: Publish the thresholds files\n      - task: PublishTestResults@2\n        condition: and(always(), eq('${{ parameters.mode }}', 'test'))\n        inputs:\n          testResultsFormat: JUnit\n          testResultsFiles: reports/pw-perf/junit.xml\n          testRunTitle: pw-perf\n          failTaskOnFailedTests: false\n          failTaskOnMissingResultsFile: false\n        displayName: Publish the test results\n      - publish: reports/pw-perf\n        artifact: pw-perf-report\n        condition: always()\n        displayName: Publish the performance report\n",
} as const;
